// Chunk splits s into at most n-sized chunks; the last chunk may be shorter.
func Chunk[T any](s []T, n int) [][]T {
	if n < 1 {
		return nil
	}
	chunks := make([][]T, 0, (len(s)+n-1)/n)
	for i := 0; i < len(s); i += n {
		end := i + n
		if end > len(s) {
			end = len(s)
		}
		chunks = append(chunks, s[i:end])
	}
	return chunks
}

