// RomanToInt converts a valid uppercase Roman numeral to its integer value.
func RomanToInt(s string) int {
	symbols := map[string]int{"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}
	sum, last := 0, 0
	for _, r := range strings.ToUpper(s) {
		v := symbols[string(r)]
		if v > last {
			sum += v - 2*last
		} else {
			sum += v
		}
		last = v
	}
	return sum
}

