func Decode(s string) string {
	var b strings.Builder
	count := 0
	for i := 0; i < len(s); i++ {
		switch {
		case s[i] >= '0' && s[i] <= '9':
			count = count*10 + int(s[i]-'0')
		default:
			b.WriteByte(s[i])
			for j := 0; j < count; j++ {
				b.WriteByte(s[i])
			}
			count = 0
		}
	}
	return b.String()
}

