// Caesar shifts each ASCII letter forward by n (mod 26), wrapping around
// both the upper and lower case alphabets, and leaves non-letters untouched.
func Caesar(s string, n int) string {
	shift := func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z':
			return 'a' + (r-'a'+rune(n))%26
		case r >= 'A' && r <= 'Z':
			return 'A' + (r-'A'+rune(n))%26
		}
		return r
	}
	out := []rune(s)
	for i, r := range out {
		out[i] = shift(r)
	}
	return string(out)
}

