// Ring is a circular buffer of ints.
type Ring struct {
	buf  []int
	head int
	n    int
}

func NewRing(cap int) *Ring {
	return &Ring{buf: make([]int, cap)}
}

func (r *Ring) Push(v int) {
	r.buf[r.head] = v
	r.head = (r.head + 1) % len(r.buf)
	if r.n < len(r.buf) {
		r.n++
	}
}

func (r *Ring) Items() []int {
	if r.n == 0 {
		return nil
	}
	off := r.head - r.n
	if off < 0 {
		off += len(r.buf)
	}
	return append(r.buf[off:], r.buf[:off]...)
}

