// ParallelSum returns the sum of nums using exactly workers goroutines.
func ParallelSum(nums []int, workers int) int {
	jobs := make(chan int)
	sum := 0
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for n := range jobs {
				sum += n
			}
		}()
	}
	for _, n := range nums {
		jobs <- n
	}
	close(jobs)
	wg.Wait()
	return sum
}

