package sandbox

import (
	"context"
	"sync"
)

// CountUntil returns how many ints were received from ch until ctx is cancelled
// or ch is closed. It is safe to call this function multiple times on the same
// channel.
func CountUntil(ctx context.Context, ch <-chan int) int {
	var mu sync.Mutex
	n := 0
	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			select {
			case v, ok := <-ch:
				if !ok {
					return
				}
				mu.Lock()
				n++
				mu.Unlock()
			case <-ctx.Done():
				return
			case <-done:
				return
			}
		}
	}()
	<-done
	return n
}

package sandbox

import (
	"io"
	"bytes"
)

// ReadChunks reads r fully and splits the bytes into chunks of at most size.
func ReadChunks(r io.Reader, size int) ([][]byte, error) {
	var chunks [][]byte
	buf := make([]byte, size)
	for {
		n, err := io.ReadFull(r, buf)
		if n > 0 {
			chunks = append(chunks, buf[:n])
		}
		if err == io.EOF || n < size {
			return chunks, err
		}
	}
}

package sandbox

import "net/http"

// Chain applies middlewares so the FIRST one in the list is the OUTERMOST.
func Chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}
